import subprocess
import re

# Get all files with Store.GetUser calls
result = subprocess.run(
    ["grep", "-r", ".GetUser(ctx, &store.FindUser", "/bench/home/work", "--include=*.go", "-n"],
    capture_output=True, text=True
)

files_with_calls = {}
for line in result.stdout.strip().split('\n'):
    if not line:
        continue
    parts = line.split(':')
    filepath = parts[0]
    linenum = int(parts[1])

    if filepath not in files_with_calls:
        files_with_calls[filepath] = []
    files_with_calls[filepath].append(linenum)

# For each file, find the function names
results = []
for filepath in sorted(files_with_calls.keys()):
    with open(filepath, 'r') as f:
        lines = f.readlines()

    # Build a map of line -> current function
    current_func = None
    line_to_func = {}

    for i, line in enumerate(lines, 1):
        if re.match(r'^func\s+', line):
            # Extract function name
            match = re.match(r'^func\s+(?:\([^)]*\)\s+)?([a-zA-Z_][a-zA-Z0-9_]*)', line)
            if match:
                current_func = match.group(1)

        if current_func:
            line_to_func[i] = current_func

    # Find which function each call is in
    for linenum in files_with_calls[filepath]:
        if linenum in line_to_func:
            func = line_to_func[linenum]
            results.append((func, filepath))

# Output sorted and unique
for func, filepath in sorted(set(results)):
    print(f"{func} — {filepath}")
EOF
